const topics=[
 {section:'Conocer',title:'Colabora, de punta a punta',accent:'sin perder el control',lede:'Una experiencia para entender el ecosistema, preparar la integración y operar flujos cotidianos con límites explícitos.',chips:['Portal web','App móvil','Nóminas desktop'],visual:'stat',stat:'360°',statLabel:'Producto, implementación y contexto laboral en una sola ruta.',detail:{intro:'Esta capacitación es una guía interna basada en el conjunto local de 70 artículos y en fuentes normalizadas del fabricante. Ese conjunto es parcial: no representa cobertura completa de toda la base oficial.',use:'Úsala para orientar una conversación de descubrimiento, preparar una implementación y localizar las fuentes que deben verificarse para la versión instalada.',steps:['Recorre los conceptos y roles.','Prepara requisitos antes de enlazar una empresa.','Valida cada flujo en una empresa de prueba antes de operar.','Escala a revisión jurídica cualquier conclusión legal.'],limits:['Material interno de capacitación; no sustituye soporte, manual vigente ni asesoría legal.','Las funciones cambian por versión y licenciamiento.'],version:'Manual vigente local + cartas técnicas 17.2.1–19.3.5',url:MR+'integracion_de_contpaqi_nominas__con_contpaqi_colabora__print.html'}},
 {section:'Conocer',title:'Tres piezas, un mismo flujo',accent:'',lede:'Nóminas sincroniza; el portal configura y administra; la app móvil acerca servicios al colaborador.',chips:['Nominista','Supervisor','Colaborador'],image:'assets/ecosistema.png',alt:'Infografía oficial de la integración de Nóminas, portal Colabora y app móvil',detail:{intro:'CONTPAQi Colabora se documenta como una plataforma en la nube con portal web para el nominista y app móvil para el colaborador. La integración con Nóminas agrega el módulo de sincronización.',use:'Sirve cuando la organización necesita autoservicio de datos y recibos, registro de asistencia y gestión de solicitudes, sin confundir cada interfaz ni su responsable.',steps:['Nóminas desktop prepara y sincroniza empleados, catálogos, movimientos y recibos.','El módulo central web configura horarios, asistencia, líderes, invitaciones y servicios.','La app móvil permite al colaborador consultar información y operar servicios habilitados.'],limits:['La disponibilidad exacta depende de versión, configuración y licencia.','No todas las acciones ocurren automáticamente; varios flujos exigen aprobación y sincronización.'],version:'Manual de referencia, sin versión explícita',url:MR+'integracion_de_contpaqi_nominas__con_contpaqi_colabora__print.html'}},
 {section:'Conocer',title:'Quién hace qué',accent:'',lede:'El éxito depende menos de “activar una app” y más de asignar dueño, permisos y responsabilidad operativa.',chips:['Propietario nube','Nominista','Líder','Colaborador'],visual:'roles',detail:{intro:'La documentación distingue al usuario SUPERVISOR de Nóminas, al nominista que administra el portal, a líderes que autorizan solicitudes y al colaborador que usa la app.',use:'Aclara responsabilidades antes de crear la empresa, enviar invitaciones o habilitar solicitudes.',steps:['SUPERVISOR: crea o elimina la empresa y usa la identidad del dueño o correo corporativo.','Nominista: configura la empresa, sincroniza y procesa información.','Líder: revisa solicitudes cuando el flujo está habilitado.','Colaborador: consulta, registra y solicita desde los canales disponibles.'],limits:['No compartas credenciales.','La identidad nube propietaria debe elegirse deliberadamente: define la propiedad de la empresa en la nube.'],version:'17.2.1 + Manual de referencia',url:CT1721+'permiso_para_crear_eliminar_empresa_en_la_nube__acotado_al_usuario_supervisor_print.html'}},
 {section:'Implementar',title:'Antes de conectar',accent:'prepara la base',lede:'Identidad, licencia, permisos, datos de empleado y responsables deben estar listos antes del primer enlace.',chips:['Identidad Nube','Licencia','SUPERVISOR','Datos limpios'],visual:'checklist',detail:{intro:'El primer enlace no es un paso reversible sin impacto. La documentación pide iniciar con SUPERVISOR y una identidad nube del dueño o correo corporativo.',use:'Convierte esta pantalla en una reunión de preflight con TI, nómina y RH.',steps:['Confirma la versión instalada y las funciones que se usarán.','Define la identidad nube propietaria y comprueba acceso.','Valida licencia de Colabora y empresas/usuarios disponibles.','Revisa correo, celular, RFC, líder, departamento y estado de empleados.','Define quién administrará el portal y quién aprobará solicitudes.','Prepara una empresa o grupo piloto y criterio de reversa.'],limits:['Una licencia vencida puede dejar la operación en modo consulta según la versión documentada.','Desvincular puede desinvitar empleados, eliminar la empresa nube y ajustar contadores de licencia.'],version:'17.2.1, 18.1.1 y Manual de referencia',url:MR+'creacion_de_cuenta_contpaqi__nube_print.html'}},
 {section:'Implementar',title:'Enlazar y sincronizar',accent:'con intención',lede:'La conexión crea el puente; la sincronización mantiene empleados, catálogos y movimientos alineados.',chips:['Empresa','Empleados','Catálogos','Bitácora'],image:'assets/empleados.png',alt:'Captura oficial del módulo de empleados en la integración con Colabora',detail:{intro:'Desde Interfaz o el acceso “Conexión en línea con COLABORA”, Nóminas abre el flujo de identidad nube, creación o vinculación de empresa y sincronización.',use:'Aplícalo en un piloto con datos revisados. Después de cada sincronización, lee la bitácora y atiende registros rechazados.',steps:['Inicia sesión con la identidad propietaria definida.','Crea o vincula la empresa correcta.','Selecciona y sincroniza empleados y catálogos.','Revisa estatus: en Colabora, fuera de Colabora y errores.','Corrige en el sistema que es dueño del dato y vuelve a sincronizar sólo cuando corresponda.'],limits:['No interpretes “sincronizado” como validación de todos los datos de negocio.','Evita duplicar cuentas o correos; valida líderes y estado del empleado.'],version:'Manual de referencia; cambios documentados desde 17.2.1',url:MR+'conexion_en_linea_con_contpaqi_colabora__print.html'}},
 {section:'Implementar',title:'Invitar sin fricción',accent:'',lede:'La invitación funciona cuando correo, celular, empresa y rol coinciden con la identidad real del colaborador.',chips:['Correo','Celular','Empresa','Seguimiento'],image:'assets/invitaciones.png',alt:'Captura oficial de la tabla de gestión de invitaciones de CONTPAQi Colabora',detail:{intro:'Tras sincronizar empleados, Colabora permite gestionar invitaciones para que descarguen y usen la app.',use:'Haz el lanzamiento por grupos pequeños, mide activaciones y conserva un canal de soporte interno.',steps:['Verifica datos de contacto antes del envío.','Explica al colaborador qué identidad y empresa debe elegir.','Envía invitaciones por un lote piloto.','Da seguimiento a pendientes, rechazados o correos duplicados.','Documenta el procedimiento de alta, baja y cambio de empresa.'],limits:['Un envío de invitación no prueba activación ni acceso correcto.','Los escenarios con múltiples empresas requieren especial cuidado al seleccionar contexto.'],version:'Manual de referencia',url:MR+'gestion_de_invitaciones_a_colaboradores_print.html'}},
 {section:'Implementar',title:'Asistencia e incidencias',accent:'cerrar el ciclo',lede:'Colabora captura y prepara; Nóminas recibe y procesa. El periodo, el tipo de incidencia y la revisión humana importan.',chips:['Checadas','Periodo','Incidencias','Exportación'],image:'assets/incidencias.png',alt:'Captura oficial del envío de incidencias desde Colabora',detail:{intro:'El portal documenta un flujo para preparar incidencias de asistencia y bajarlas hacia Nóminas. La configuración de horarios, turnos y reglas precede a la operación.',use:'Revisa por periodo antes de exportar o descargar. Trata errores y ausencias como excepciones operativas, no como datos silenciosos.',steps:['Configura horarios, turnos, tolerancias y líderes.','Revisa checadas y excepciones.','Selecciona el periodo y las incidencias a enviar.','Descarga o integra en Nóminas según el flujo documentado.','Valida el resultado antes del cálculo.'],limits:['La captura móvil no sustituye políticas internas ni revisión.','La fuente local no adjudica una obligación legal específica a este flujo.'],version:'Manual de referencia',url:MR+'como_bajar_las_incidencias_de_contpaqi_colabora__hacia_contpaqi_nominas__print.html'}},
 {section:'Implementar',title:'Recibos electrónicos',accent:'disponibles',lede:'El envío masivo puede activar Colabora y poner XML/PDF al alcance del colaborador, con tiempos y condiciones operativas.',chips:['XML','PDF','Envío masivo','Proceso asíncrono'],image:'assets/recibos.png',alt:'Captura oficial del envío masivo de recibos electrónicos hacia CONTPAQi Colabora',detail:{intro:'La documentación describe la activación de Colabora desde el envío masivo de recibos electrónicos y la carga asíncrona de CFDI.',use:'Planea el primer envío fuera de una ventana crítica y confirma que la empresa e identidades quedaron correctamente vinculadas.',steps:['Selecciona el envío masivo en Nóminas.','Confirma el proceso de creación o uso de empresa Colabora.','Espera la carga asíncrona.','Verifica disponibilidad desde el perfil de un colaborador piloto.','Atiende errores antes de ampliar el lote.'],limits:['La referencia estima hasta ~5 min para crear una empresa con 500 colaboradores; cargas de 500 CFDI pueden rondar 25 min y 1000 CFDI 60 min. Son referencias del caso documentado, no SLA.','Una corrección en 19.2.2 atendió fallos de sincronización de recibos timbrados.'],version:'Caso práctico 2025; corrección 19.2.2',url:CPREC+'activa_contpaqi_colabora__desde_el_envio_masivo_de_recibos_electronicos_print.html'}},
 {section:'Implementar',title:'Vacaciones y permisos',accent:'con conciliación',lede:'Configurar saldos, tipos y autorizadores viene antes de solicitar. Aprobar y sincronizar viene antes de pagar.',chips:['Saldos','Solicitudes','Aprobación','Sincronización'],image:'assets/vacaciones.png',alt:'Captura oficial de la sincronización inicial de vacaciones y prestaciones',detail:{intro:'La versión 19.3.5 documenta configuración inicial, saldos, solicitudes, autorización y sincronización bidireccional de vacaciones.',use:'Opera el flujo como cadena controlada: dato inicial → solicitud → aprobación → sincronización → validación en prenómina y sobre-recibo.',steps:['Configura tipos de solicitud, saldos y políticas en Colabora.','El colaborador solicita desde app o WhatsApp cuando esté habilitado.','Líder y nominista revisan y aplican.','Nóminas sincroniza y genera tarjetas.','La bitácora muestra integraciones y conflictos.','Valida fecha de pago, prima vacacional y cruces con otras incidencias.'],limits:['Un conflicto con una incidencia previa puede bloquear la integración y aparecer en observaciones.','La fecha de pago toma como referencia el primer día solicitado según el flujo documentado.'],version:'19.3.5 + Manual de referencia',url:CT1935+'proceso_de_autorizacion_y_sincronizacion_de_vacaciones_print.html'}},
 {section:'Implementar',title:'Colabora en WhatsApp',accent:'otro canal',lede:'El asistente acerca consultas y solicitudes, pero necesita identidad activa, celular correcto y servicios configurados.',chips:['Sesión activa','Celular','Consultas','Solicitudes'],image:'assets/whatsapp.png',imageClass:'phone',alt:'Captura oficial de la app Colabora con acceso a Colabora WhatsApp',detail:{intro:'El manual documenta acceso desde la app y servicios como perfil, asistencia, recibos, solicitudes, días disponibles, historial y selección de empresa.',use:'Habilita sólo después de validar el celular del empleado y probar la experiencia con distintos roles y empresas.',steps:['Registra correctamente el celular en Empleados.','Comprueba la sesión de Identidad Nube.','Abre Colabora WhatsApp desde la app.','Prueba consultas y solicitudes con datos no confidenciales.','Verifica el cambio de empresa para usuarios multiempresa.'],limits:['El asistente valida fechas y políticas configuradas; no decide por sí solo la procedencia laboral de una solicitud.','No expongas información real de empleados en demos o capturas.'],version:'Manual de referencia, sin versión explícita',url:MR+'gestion_de_servicios_en_colabora_whatsapp_1_print.html'}},
 {section:'Relacionar',title:'Personia y Nóminas Nube',accent:'sin extrapolar',lede:'La evidencia local sí vincula a Personia con la app Colabora; no documenta aquí una implementación equivalente a la de Nóminas desktop.',chips:['Personia','Nóminas Nube','Evidencia acotada'],visual:'personia',detail:{intro:'El manual de integración afirma que la app permite a colaboradores procesados en CONTPAQi Nóminas y CONTPAQi Personia autogestionar datos, recibos y asistencia.',use:'Presenta esta relación como capacidad mencionada por el fabricante, no como un instructivo completo de Personia/Nóminas Nube.',steps:['Distingue Nóminas desktop de Personia/Nóminas Nube.','Conserva el nombre histórico “Personia” cuando la fuente lo usa.','Antes de implementar con Nóminas Nube, exige documentación específica, versión y alcance.'],limits:['No se encontró en el conjunto local un paso a paso equivalente para enlazar Nóminas Nube/Personia.','La fase independiente de funcionalidades laborales fuera de Colabora sigue pendiente.'],version:'Manual de referencia; mención explícita de Personia',url:MR+'integracion_de_contpaqi_nominas__con_contpaqi_colabora__print.html'}},
 {section:'Relacionar',title:'Reforma laboral',accent:'separa obligación y herramienta',lede:'Colabora puede apoyar procesos de RH; la evidencia disponible no vincula automáticamente funciones con artículos legales vigentes.',chips:['Proceso ≠ cumplimiento','Brecha legal visible','Revisión humana'],visual:'legal',detail:{intro:'El material local no adjudica obligaciones, artículos ni vigencia legal a funciones específicas de Colabora. Por eso esta capacitación separa capacidad técnica, proceso de negocio y obligación jurídica.',use:'Úsalo como mapa de preguntas para una revisión posterior con fuente legal primaria y asesoría competente.',steps:['Asistencia: puede aportar registros; falta vincular obligación, conservación y reglas aplicables.','Recibos: facilita disponibilidad; falta adjudicar efectos legales y requisitos de entrega.','Vacaciones y permisos: ordena solicitud y autorización; falta validar reglas, saldos y evidencia exigible.','Datos e identidad: apoya trazabilidad; falta determinar privacidad, retención y responsabilidades.'],limits:['No afirmar que Colabora garantiza cumplimiento.','No convertir documentación comercial o técnica en interpretación jurídica.','Toda referencia legal debe registrar jurisdicción, artículo, reforma, vigencia y fecha de consulta.'],version:'Mapa de brechas local, 2026-10-12',url:MR+'integracion_de_contpaqi_nominas__con_contpaqi_colabora__print.html'}},
 {section:'Cerrar',title:'Tu siguiente movimiento',accent:'piloto controlado',lede:'Empieza pequeño, observa el ciclo completo y documenta los puntos de decisión antes de escalar.',chips:['1 empresa','1 grupo','1 periodo','1 revisión'],visual:'final',detail:{intro:'Una adopción útil se demuestra con un flujo completo y repetible, no con una pantalla enlazada.',use:'Convierte el aprendizaje en un piloto con aceptación humana.',steps:['Selecciona una empresa y un grupo representativo.','Congela alcance, versión y servicios a probar.','Ejecuta identidad → enlace → sincronización → invitación → flujo operativo.','Registra incidencias, responsables, tiempos y reversa.','Pide revisión de nómina, RH, TI y, cuando aplique, legal.','Sólo después decide si escalar.'],limits:['Este paquete no publica, no cambia SQLite y no modifica contratos del renderer.','La aceptación final del contenido y su uso operativo corresponde al equipo ExpIRITi.'],version:'Resumen ejecutivo interno v1',url:MR+'integracion_de_contpaqi_nominas__con_contpaqi_colabora__print.html'}}
];

