let currentSlide=0;
let returnFocus=null;
let progressFrame=0;
const byId=id=>document.getElementById(id);
const stageSlide=byId('slide');
const topicMenu=byId('topicMenu');
const modalBackdrop=byId('modalBackdrop');
const modalDialog=byId('modal');
const modalContent=byId('modalContent');
const lightboxBackdrop=byId('lightboxBackdrop');
const lightbox=lightboxBackdrop.querySelector('.lightbox');
const htmlEscape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));

function focusWithoutScroll(element){element?.focus({preventScroll:true});}
function imageUrl(path){return new URL(path,document.baseURI).href;}
function visualMarkup(topic){
  if(topic.image){
    const src=imageUrl(topic.image);
    return `<div class="visual"><button class="image-trigger" type="button" data-image-src="${htmlEscape(src)}" data-image-alt="${htmlEscape(topic.alt)}" aria-label="Ampliar captura: ${htmlEscape(topic.alt)}"><img class="${topic.imageClass||''}" src="${htmlEscape(src)}" alt="${htmlEscape(topic.alt)}" loading="eager" decoding="async"></button></div>`;
  }
  if(topic.visual==='stat')return `<div class="visual"><div class="big-stat">${topic.stat}<small>${topic.statLabel}</small></div></div>`;
  if(topic.visual==='roles')return `<div class="visual"><div class="diagram"><div class="diagram-node accent"><strong>SUPERVISOR</strong><small>Propiedad nube y creación de empresa</small></div><div class="flow"><div class="diagram-node"><strong>Nominista</strong><small>Configura y sincroniza</small></div><div class="diagram-node"><strong>Líder</strong><small>Revisa solicitudes</small></div><div class="diagram-node"><strong>Colaborador</strong><small>Consulta y solicita</small></div></div></div></div>`;
  if(topic.visual==='checklist')return `<div class="visual"><div class="diagram"><div class="big-stat">04<small>condiciones antes de enlazar</small></div>${['Identidad propietaria','Licencia disponible','Permisos correctos','Datos listos'].map((text,i)=>`<div class="diagram-node"><strong>0${i+1} · ${text}</strong></div>`).join('')}</div></div>`;
  if(topic.visual==='personia')return `<div class="visual"><div class="diagram"><div class="diagram-node accent"><strong>Nóminas Nube</strong><small>Activa Colabora desde el acceso directo de la empresa abierta.</small></div><div class="diagram-node"><strong>Portal Colabora</strong><small>Verifica la empresa y configura los servicios después de activar.</small></div></div></div>`;
  if(topic.visual==='legal')return `<div class="visual"><div class="diagram"><div class="diagram-node accent"><strong>Colabora puede apoyar</strong><small>Solicitudes, recibos y registros operativos.</small></div><div class="diagram-node"><strong>La empresa conserva</strong><small>Cálculo, autorización, políticas, privacidad y resguardo documental.</small></div></div></div>`;
  return `<div class="visual"><div class="diagram"><div class="diagram-node accent"><strong>Un ciclo completo</strong><small>Una empresa · un grupo · un proceso real</small></div><div class="flow"><div class="diagram-node"><strong>Configurar</strong></div><div class="diagram-node"><strong>Probar</strong></div><div class="diagram-node"><strong>Comprobar</strong></div></div></div></div>`;
}

function popupData(){return globalThis.COLABORA_AUDITED_POPUPS?.[currentSlide]||null;}
function popupSources(){const popup=popupData();return popup?.sources||depth[currentSlide].sources;}
function renderMain(){
  const topic=topics[currentSlide],copy=editorial[currentSlide],detail=depth[currentSlide],sources=popupSources(),leadSource=sources[0];
  stageSlide.innerHTML=`<div class="slide-copy"><p class="eyebrow">${htmlEscape(topic.section)} · ${String(currentSlide+1).padStart(2,'0')}</p><h1>${htmlEscape(copy.title)}</h1><p class="lede">${htmlEscape(copy.lede)}</p><ul class="slide-points">${copy.points.map(point=>`<li><b>${htmlEscape(point[0])}</b><span>${htmlEscape(point[1])}</span></li>`).join('')}</ul><button class="detail-button" id="detailButton" type="button">Ver guía técnica <span aria-hidden="true">→</span></button><div class="slide-source"><span>Fuente</span><a href="${leadSource[2]}" target="_blank" rel="noreferrer">${htmlEscape(leadSource[0])} · ${htmlEscape(leadSource[1])}</a>${sources.length>1?`<button id="sourceMore" type="button" aria-label="Ver las ${sources.length} fuentes de este tema">+${sources.length-1}</button>`:''}</div></div>${visualMarkup(topic)}`;
  byId('detailButton').addEventListener('click',openProcedure);
  byId('sourceMore')?.addEventListener('click',openProcedure);
  stageSlide.querySelector('.image-trigger')?.addEventListener('click',event=>openLightbox(event.currentTarget));
  byId('counter').textContent=`${currentSlide+1} de ${topics.length}`;
  byId('progressText').textContent=`${String(currentSlide+1).padStart(2,'0')} / ${topics.length}`;
  byId('sectionName').textContent=topic.section;
  byId('progressBar').style.width=`${((currentSlide+1)/topics.length)*100}%`;
  document.title=`${copy.title} · Colabora 360`;
  drawTopicMenu();
}

function drawTopicMenu(){
  let section='';
  topicMenu.innerHTML=topics.map((topic,i)=>{const heading=topic.section!==section?`<div class="menu-section">${section=topic.section}</div>`:'';return `${heading}<button class="menu-item ${i===currentSlide?'active':''}" role="menuitem" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span><b>${htmlEscape(editorial[i].title)}</b></button>`}).join('');
  topicMenu.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>{currentSlide=Number(button.dataset.index);closeTopicMenu();renderMain();focusWithoutScroll(stageSlide);}));
}

function moveMain(delta){currentSlide=(currentSlide+delta+topics.length)%topics.length;renderMain();focusWithoutScroll(stageSlide);}
function compactSourceLabel(source,index,allSources){
  const title=source[0],version=source[1];
  if(title.includes('art. 804'))return 'LFT · art. 804';
  if(title.includes('art. 101'))return 'LFT · art. 101';
  if(title.includes('arts. 76'))return 'LFT · vacaciones';
  if(title==='Ley Federal del Trabajo')return 'LFT vigente';
  if(title==='Decreto vacaciones dignas')return 'DOF · vacaciones';
  if(title==='Manual Colabora')return 'Manual Colabora';
  const repeated=allSources.filter(item=>item[1]===version).length>1;
  if(repeated)return `${version} · ${title.replace('CONTPAQi ','').slice(0,22)}`;
  if(/^(Manual|actualizado|Nóminas Nube|mención histórica|capacidad)/i.test(version))return title.replace('CONTPAQi ','').slice(0,28);
  return version;
}
function sourceSelectorItems(sources){
  const described=versionNavigation[currentSlide]||[];
  return sources.map((source,index)=>{
    const custom=described.find(item=>item.source===index+1);
    return custom||{label:compactSourceLabel(source,index,sources),source:index+1,title:source[0],text:source[1]};
  });
}
function documentationMarkup(sources){
  if(sources.length===1){
    const source=sources[0];
    return `<a class="direct-document" href="${source[2]}" target="_blank" rel="noreferrer"><strong>${htmlEscape(source[0])}</strong><span>${htmlEscape(source[1])} · Abrir fuente oficial ↗</span></a>`;
  }
  const items=sourceSelectorItems(sources);
  return `<section class="version-experience"><div class="version-tabs" role="tablist" aria-label="Documentos y versiones aplicables">${items.map((item,i)=>`<button class="version-tab" type="button" role="tab" aria-selected="${i===0}" data-version-index="${i}">${htmlEscape(item.label)}</button>`).join('')}</div><div class="version-panel" id="versionPanel"></div></section>`;
}
function renderVersionPanel(selected=0){
  const sources=popupSources();
  if(sources.length<2)return;
  const items=sourceSelectorItems(sources),item=items[selected],source=sources[item.source-1];
  byId('versionPanel').innerHTML=`<h4><a href="${source[2]}" target="_blank" rel="noreferrer">${htmlEscape(source[0])} ↗</a></h4>${item.text?`<p>${htmlEscape(item.text)}</p>`:''}`;
  modalContent.querySelectorAll('.version-tab').forEach((button,i)=>button.setAttribute('aria-selected',String(i===selected)));
}
function procedureMarkup(){
  const copy=editorial[currentSlide],detail=depth[currentSlide],popup=popupData(),sources=popupSources();
  if(!popup)return '';
  const list=(title,items,kind='ul')=>items?.length?`<section class="audited-block"><h3>${htmlEscape(title)}</h3><${kind}>${items.map(value=>`<li>${htmlEscape(value)}</li>`).join('')}</${kind}></section>`:'';
  const steps=popup.procedure.map((step,i)=>{const source=sources[step[3]-1];return `<li><strong>${String(i+1).padStart(2,'0')}</strong><div><span class="actor">${htmlEscape(step[0])}</span><p>${htmlEscape(step[1])} <a href="${source[2]}" target="_blank" rel="noreferrer" aria-label="Abrir fuente ${step[3]}: ${htmlEscape(source[0])}">[${step[3]}]</a></p><small>Resultado: ${htmlEscape(step[2])}</small></div></li>`}).join('');
  const procedure=popup.procedure.length?`<section class="audited-block"><h3>${htmlEscape(popup.procedureTitle)}</h3><ol class="workflow procedure">${steps}</ol></section>`:'';
  const result=popup.resultTitle?list(popup.resultTitle,popup.result):'';
  const warnings=popup.warningsTitle&&popup.warnings?.length?`<section class="audited-block"><h3>${htmlEscape(popup.warningsTitle)}</h3><div class="callout caution"><ul>${popup.warnings.map(value=>`<li>${htmlEscape(value)}</li>`).join('')}</ul></div></section>`:'';
  return `<section class="dialog-sources"><div class="dialog-sources-head"><h3>Documentación</h3><span>${htmlEscape(popup.applicability||dialogApplicability[currentSlide]||detail.productVersion)}</span></div>${documentationMarkup(sources)}<p class="scope-summary">${htmlEscape(popup.scope||dialogScopes[currentSlide])}</p></section><p class="dialog-intro">${htmlEscape(popup.intro)}</p>${list(popup.contextTitle,popup.context)}${list(popup.requirementsTitle,popup.requirements)}${procedure}${result}${warnings}`;
}

function updateDialogProgress(){
  cancelAnimationFrame(progressFrame);
  progressFrame=requestAnimationFrame(()=>{const maximum=modalContent.scrollHeight-modalContent.clientHeight;const progress=maximum<=0?100:Math.max(0,Math.min(100,(modalContent.scrollTop/maximum)*100));byId('dialogProgressBar').style.width=`${progress}%`;});
}
function refreshProcedure(){
  const topic=topics[currentSlide],copy=editorial[currentSlide],popup=popupData();
  byId('modalEyebrow').textContent=`${topic.section} · ${String(currentSlide+1).padStart(2,'0')} · ${popup?.meta||`${copy.procedure.length} pasos`}`;
  byId('modalTitle').textContent=copy.title;
  byId('dialogPosition').textContent=`Tema ${currentSlide+1} de ${topics.length}`;
  modalContent.innerHTML=procedureMarkup();
  modalContent.scrollTop=0;
  modalContent.querySelectorAll('.version-tab').forEach((button,i)=>button.addEventListener('click',()=>renderVersionPanel(i)));
  renderVersionPanel(0);
  renderMain();
  updateDialogProgress();
}
function openProcedure(){returnFocus=document.activeElement;modalBackdrop.hidden=false;document.body.classList.add('overlay-open');refreshProcedure();modalContent.scrollTop=0;updateDialogProgress();focusWithoutScroll(byId('closeButton'));}
function closeProcedure(){if(modalBackdrop.hidden)return;modalBackdrop.hidden=true;document.body.classList.remove('overlay-open');byId('dialogProgressBar').style.width='0%';focusWithoutScroll(returnFocus);}
function moveProcedure(delta){currentSlide=(currentSlide+delta+topics.length)%topics.length;refreshProcedure();focusWithoutScroll(delta<0?byId('dialogPrev'):byId('dialogNext'));}

function openLightbox(trigger){
  returnFocus=trigger;
  const image=byId('lightboxImage');
  image.src=trigger.dataset.imageSrc;image.alt=trigger.dataset.imageAlt;
  byId('lightboxTitle').textContent=editorial[currentSlide].title;
  resetZoom();
  lightboxBackdrop.hidden=false;document.body.classList.add('overlay-open');focusWithoutScroll(byId('lightboxClose'));
}
function resetZoom(){const canvas=byId('lightboxCanvas'),image=byId('lightboxImage'),button=byId('zoomButton');canvas.classList.remove('zoomed','is-panning');canvas.scrollTo(0,0);image.style.height='';image.style.width='';button.setAttribute('aria-pressed','false');button.setAttribute('aria-label','Ampliar imagen');button.title='Ampliar imagen';}
function closeLightbox(){if(lightboxBackdrop.hidden)return;resetZoom();lightboxBackdrop.hidden=true;document.body.classList.remove('overlay-open');byId('lightboxImage').removeAttribute('src');focusWithoutScroll(returnFocus);}
function toggleZoom(){const canvas=byId('lightboxCanvas'),image=byId('lightboxImage'),button=byId('zoomButton');if(canvas.classList.contains('zoomed')){resetZoom();return;}canvas.classList.add('zoomed');image.style.height=`${Math.ceil(Math.max(canvas.clientHeight*1.55,image.naturalHeight*1.2))}px`;image.style.width='auto';button.setAttribute('aria-pressed','true');button.setAttribute('aria-label','Ajustar imagen a la ventana');button.title='Ajustar imagen a la ventana';requestAnimationFrame(()=>canvas.scrollTo({left:(canvas.scrollWidth-canvas.clientWidth)/2,top:(canvas.scrollHeight-canvas.clientHeight)/2,behavior:'auto'}));}
const imagePan={active:false,pointerId:null,startX:0,startY:0,startLeft:0,startTop:0};
function beginImagePan(event){const canvas=byId('lightboxCanvas');if(!canvas.classList.contains('zoomed')||event.button!==0)return;imagePan.active=true;imagePan.pointerId=event.pointerId;imagePan.startX=event.clientX;imagePan.startY=event.clientY;imagePan.startLeft=canvas.scrollLeft;imagePan.startTop=canvas.scrollTop;canvas.classList.add('is-panning');canvas.setPointerCapture?.(event.pointerId);event.preventDefault();}
function moveImagePan(event){if(!imagePan.active||event.pointerId!==imagePan.pointerId)return;const canvas=byId('lightboxCanvas');canvas.scrollLeft=imagePan.startLeft-(event.clientX-imagePan.startX);canvas.scrollTop=imagePan.startTop-(event.clientY-imagePan.startY);event.preventDefault();}
function endImagePan(event){if(!imagePan.active||event.pointerId!==imagePan.pointerId)return;const canvas=byId('lightboxCanvas');imagePan.active=false;canvas.classList.remove('is-panning');if(canvas.hasPointerCapture?.(event.pointerId))canvas.releasePointerCapture(event.pointerId);imagePan.pointerId=null;}
function toggleTopicMenu(){const open=topicMenu.classList.toggle('open');byId('topicButton').setAttribute('aria-expanded',String(open));if(open)focusWithoutScroll(topicMenu.querySelector('button.active'));}
function closeTopicMenu(){topicMenu.classList.remove('open');byId('topicButton').setAttribute('aria-expanded','false');}
function toggleTheme(){const root=document.documentElement,dark=root.dataset.theme!=='dark';root.dataset.theme=dark?'dark':'light';byId('themeToggle').setAttribute('aria-label',dark?'Cambiar a tema claro':'Cambiar a tema oscuro');localStorage.setItem('colabora-theme',root.dataset.theme);}
function trapFocus(event,container){const focusable=[...container.querySelectorAll('button,a[href],[tabindex]:not([tabindex="-1"])')].filter(item=>!item.hasAttribute('disabled'));if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}

byId('nextButton').addEventListener('click',()=>moveMain(1));
byId('prevButton').addEventListener('click',()=>moveMain(-1));
byId('brandHome').addEventListener('click',event=>{event.preventDefault();currentSlide=0;renderMain();focusWithoutScroll(stageSlide);});
byId('topicButton').addEventListener('click',toggleTopicMenu);
byId('themeToggle').addEventListener('click',toggleTheme);
byId('closeButton').addEventListener('click',closeProcedure);
byId('dialogPrev').addEventListener('click',()=>moveProcedure(-1));
byId('dialogNext').addEventListener('click',()=>moveProcedure(1));
modalContent.addEventListener('scroll',updateDialogProgress,{passive:true});
modalBackdrop.addEventListener('click',event=>{if(event.target===modalBackdrop)closeProcedure();});
byId('lightboxClose').addEventListener('click',closeLightbox);
byId('zoomButton').addEventListener('click',toggleZoom);
byId('lightboxCanvas').addEventListener('pointerdown',beginImagePan);
byId('lightboxCanvas').addEventListener('pointermove',moveImagePan);
byId('lightboxCanvas').addEventListener('pointerup',endImagePan);
byId('lightboxCanvas').addEventListener('pointercancel',endImagePan);
byId('lightboxImage').addEventListener('dragstart',event=>event.preventDefault());
lightboxBackdrop.addEventListener('click',event=>{if(event.target===lightboxBackdrop)closeLightbox();});
document.addEventListener('click',event=>{if(!event.target.closest('.topic-wrap'))closeTopicMenu();});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'){if(!lightboxBackdrop.hidden)closeLightbox();else if(!modalBackdrop.hidden)closeProcedure();else closeTopicMenu();return;}
  if(!lightboxBackdrop.hidden){if(event.key==='Tab')trapFocus(event,lightbox);return;}
  if(!modalBackdrop.hidden){if(event.key==='Tab')trapFocus(event,modalDialog);return;}
  if(topicMenu.classList.contains('open'))return;
  if(['ArrowRight','PageDown'].includes(event.key)){event.preventDefault();moveMain(1);}
  if(['ArrowLeft','PageUp'].includes(event.key)){event.preventDefault();moveMain(-1);}
  if(event.key==='Home'){event.preventDefault();currentSlide=0;renderMain();focusWithoutScroll(stageSlide);}
  if(event.key==='End'){event.preventDefault();currentSlide=topics.length-1;renderMain();focusWithoutScroll(stageSlide);}
});

const savedTheme=localStorage.getItem('colabora-theme');
if(savedTheme==='dark')document.documentElement.dataset.theme='dark';
renderMain();
